/**
 * Obtiene una variante de imagen para una categoría clínica.
 * Permite seleccionar determinísticamente mediante un texto semilla o aleatoriamente.
 */
export function getCatalogVariant(category: string, seed?: string): string | null {
  const list = MASSIVE_CLINICAL_CATALOG[category];
  if (!list || list.length === 0) return null;
  if (list.length === 1) return list[0];

  if (seed) {
    let hash = 0;
    for (let i = 0; i < seed.length; i++) {
      hash = ((hash << 5) - hash) + seed.charCodeAt(i);
      hash |= 0;
    }
    const idx = Math.abs(hash) % list.length;
    return list[idx];
  }

  const randomIdx = Math.floor(Math.random() * list.length);
  return list[randomIdx];
}
